19	import java.time.Clock;
20	import java.time.LocalDate;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Supplies an owner's registration date when the client did not provide one.
27	 * <p>
28	 * A registration date is optional on create; when absent it defaults to the server's
29	 * current date so every stored owner carries the day it was registered. An explicitly
30	 * supplied date is left untouched.
31	 */
32	@Component
33	public class RegistrationDateDefaulter {
34	
35	    private final Clock clock;
36	
37	    public RegistrationDateDefaulter(Clock clock) {
38	        this.clock = clock;
39	    }
40	
41	    /**
42	     * Sets {@code owner}'s registration date to the server's current date unless one was
43	     * already supplied.
44	     *
45	     * @param owner the owner being created
46	     */
47	    public void applyDefault(Owner owner) {
48	        if (owner.getRegistrationDate() == null) {
49	            owner.setRegistrationDate(LocalDate.now(clock));
50	        }
51	    }
52	}
