23	/**
24	 * Assigns owners who deliberately share a household (via the {@code sharesHousehold} flag)
25	 * the household's stable shared identifier, back-filling any existing member that does not
26	 * yet carry it so the whole household ends up tagged with the same value.
27	 */
28	@Component
29	public class HouseholdAssigner {
30	
31	    private final HouseholdMatcher householdMatcher;
32	
33	    private final ClinicService clinicService;
34	
35	    public HouseholdAssigner(HouseholdMatcher householdMatcher, ClinicService clinicService) {
36	        this.householdMatcher = householdMatcher;
37	        this.clinicService = clinicService;
38	    }
39	
40	    /**
41	     * Tags {@code candidate} with its household's shared identifier and back-fills the same
42	     * value onto existing members that lack one. The candidate is not saved here; the
43	     * caller persists it as part of the create.
44	     *
45	     * @param candidate the owner being created into an existing household
46	     * @return the shared household identifier applied to the candidate
47	     */
48	    public String assign(Owner candidate) {
49	        String householdId = householdMatcher.householdId(candidate);
50	        candidate.setHouseholdId(householdId);
51	        for (Owner member : householdMatcher.findMembers(candidate)) {
52	            if (member.getHouseholdId() == null) {
53	                member.setHouseholdId(householdId);
54	                clinicService.saveOwner(member);
55	            }
56	        }
57	        return householdId;
58	    }
59	}
